    },
    {
      "name": "Bookmark",
      "description": "Saved link to a Discussion Thread for later access"
    },
    {
      "name": "Category",
      "description": "Grouping used to organize related Discussion Threads",
      "attributes": [
        "Topic",
        "Discussion Thread"
      ]
    },
    {
      "name": "Lock",
      "description": "State preventing new Posts in a Discussion Thread"
    },
    {
      "name": "System",
      "description": "Automated process handling recommendations and notifications"
    },
    {
      "name": "Recommendation",
      "description": "Suggested Discussion Threads for a User",
      "attributes": [
        "Discussion Thread"
      ]
    },
    {
      "name": "Notification",
      "description": "Message informing a User about activity related to them"
    }
  ]
}
